export function getRealClubLogo(name: string, shortName?: string, _code?: string): string | null {
  const norm = (s?: string) =>
    (s || "")
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/ø/g, "o")
      .replace(/ł/g, "l")
      .replace(/ı/g, "i")
      .replace(/ß/g, "ss")
      .replace(/[^a-z0-9]/g, "")
      .trim();

  const cleanName = norm(name);
  const cleanNameNoWomen = norm((name || "").replace(/\bwomen\b/gi, ""));
  const cleanShort = norm(shortName);

  if (cleanName && REAL_CLUB_LOGOS[cleanName]) return REAL_CLUB_LOGOS[cleanName];
  if (cleanNameNoWomen && REAL_CLUB_LOGOS[cleanNameNoWomen]) return REAL_CLUB_LOGOS[cleanNameNoWomen];
  if (cleanShort && REAL_CLUB_LOGOS[cleanShort]) return REAL_CLUB_LOGOS[cleanShort];

  // Deterministic prefix/suffix stripping ONLY (never arbitrary substring/3-letter code matching)
  const stripped = cleanNameNoWomen.replace(/^(fc|cf|sc|ac|cd|ud|sd|rc|ca|as|us|ss|fk|sk|bk|ik|nk|gnk|hnk)|(fc|cf|sc|ac|afc|utd|united|women)$/g, "");
  if (stripped.length >= 4 && REAL_CLUB_LOGOS[stripped]) {
    return REAL_CLUB_LOGOS[stripped];
  }

  return null;
}
